import { useState } from "react";
import {
  type LofiState,
  lofiDevice,
} from "@/components/audio-ui/devices/lofi/device";
import { createLofiEngine } from "@/components/audio-ui/devices/lofi/engine";
import { LofiPanel } from "@/components/audio-ui/devices/lofi/panel";
import { useDeviceLoop } from "@/hooks/use-device-loop";
import { useDeviceSignal } from "@/hooks/use-device-signal";
import { useMasterBus } from "@/hooks/use-master-bus";
import { useDemoSound } from "@/hooks/use-demo-source";

const MASTER_VOLUME = 0.7;

/**
 * A lo-fi you can plug in: its state, a panel that draws the band it leaves
 * and an engine that plays it, each its own file and none knowing the others.
 * Play the loop and turn up the wow and the crackle: it ages like a worn tape.
 */
export function BlockLofi() {
  const [state, setState] = useState<LofiState>(() => lofiDevice.defaults());
  const master = useMasterBus(MASTER_VOLUME);
  const sound = useDemoSound("groove");
  const { engine } = useDeviceLoop({
    create: createLofiEngine,
    destination: master,
    sound,
    state,
  });
  const signal = useDeviceSignal(engine, lofiDevice);
  return (
    <div className="rounded-2xl h-full w-full min-w-0">
      <LofiPanel onValueChange={setState} signal={signal} value={state} />
    </div>
  );
}
